from pathlib import Path
import hashlib,json,subprocess
W=Path('/home/jspitz/.codex/worktrees/native-quality-scans/JSimplex.jl');D=W/'diagnostics/klu-umfpack/2026-10-29'
def digest(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def git(*a):return subprocess.check_output(['git',*a],cwd=W,text=True).strip()
def need(v,m):
 if not v:raise RuntimeError(m)
need(git('rev-parse','HEAD')=='f9f1e9b4076bd541150dedba8df26efc6429d34a','base')
need(git('rev-parse','master')==git('rev-parse','origin/master')=='c0fa748ffa61ccb7c1caaf248c40324f60bc737b','master')
initial=json.loads((D/'STAGED.json').read_text())
for name,h in initial['files'].items():need(digest(W/name)==h,'initial staged hash preserved '+name)
need(git('diff','--cached','--name-only').splitlines()==sorted([*initial['files'],str((D/'STAGED.json').relative_to(W))]),'original exact staged list preserved')
raw=(D/'summary.csv').read_bytes()
need(digest(D/'summary.csv')=='d676a8a4dab16bad221798a8ab238a41d4c61dcf6fdadb56525a25961a1e9802','reviewed raw CSV preserved')
need(raw.count(b'\r\n')==25 and b'\n' not in raw.replace(b'\r\n',b''),'CSV only canonical CRLF')
need(all(not line.endswith((b' ',b'\t')) for line in raw.split(b'\r\n')),'no space/tab before CRLF')
record=dict(scope='publication-only supplement; no numerical/auditor rerun or evidence rewrite',cause='csv.writer default CRLF is flagged by Git whitespace check',initial_publication='stopped before commit/push',CSV_sha256=digest(D/'summary.csv'),CRLF_rows=25,raw_preserved=True,reviewed_CSV_hash_unchanged=True,rule='exclude verbatim upstream/copied input and raw generated CSV from authored LF whitespace gate; keep every other authored file strict')
(D/'WHITESPACE-SUPPLEMENT.json').write_text(json.dumps(record,indent=2)+'\n')
files=sorted(p for p in D.rglob('*') if p.is_file() and '__pycache__' not in str(p))
final=D/'STAGED-FINAL.json';need(not final.exists(),'fresh final manifest')
final.write_text(json.dumps(dict(scope='exact complete final staged files; hashes exclude self only',files={str(p.relative_to(W)):digest(p) for p in files}),indent=2)+'\n');files.append(final)
names=sorted(str(p.relative_to(W)) for p in files)
git('add','--',*names);need(git('diff','--cached','--name-only').splitlines()==names,'complete staged set')
for n in names:need(hashlib.sha256(subprocess.check_output(['git','show',':'+n],cwd=W)).hexdigest()==digest(W/n),'staged blob '+n)
verbatim=lambda n: '/vendor/' in n or '/native-source/' in n or n.endswith(('/inputs.toml','/summary.csv'))
subprocess.run(['git','diff','--cached','--check','--',*[n for n in names if not verbatim(n)]],cwd=W,check=True)
r=subprocess.run(['git','diff','--cached','--check','--',*[n for n in names if verbatim(n)]],cwd=W,text=True,capture_output=True)
seal=dict(exact_names=names,blobs={n:digest(W/n) for n in names},publication_pass=True,raw_whitespace=dict(returncode=r.returncode,diagnostics=r.stdout+r.stderr))
Path('/tmp/klu-bench-20261029/publication-seal.json').write_text(json.dumps(seal,indent=2)+'\n')
print(json.dumps(dict(publication_pass=True,exact_files=len(names),all_initial_hashes_preserved=True,raw_csv_preserved=True,authored_whitespace_pass=True)))
